import hashlib
import hmac
import os
import time
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import json
import secrets
import re

SECRET_KEY = os.environ.get('APP_SECRET', secrets.token_hex(32))
SESSION_STORE = {}
SESSION_LOCK = threading.Lock()
RATE_LIMITS = {}
RATE_LIMIT_LOCK = threading.Lock()

def constant_time_compare(a, b):
    """Constant-time comparison to prevent timing attacks."""
    if not isinstance(a, bytes):
        a = a.encode('utf-8')
    if not isinstance(b, bytes):
        b = b.encode('utf-8')
    return hmac.compare_digest(a, b)

def generate_session_id():
    return secrets.token_hex(32)

def compute_mac(message):
    return hmac.new(SECRET_KEY.encode(), message.encode(), hashlib.sha256).hexdigest()

def create_session(user_id, role='user'):
    session_id = generate_session_id()
    session_data = {
        'user_id': user_id,
        'role': role,
        'created_at': time.time(),
        'expires_at': time.time() + 3600
    }
    with SESSION_LOCK:
        SESSION_STORE[session_id] = session_data
    return session_id

def validate_session(session_id):
    with SESSION_LOCK:
        session = SESSION_STORE.get(session_id)
    if session is None:
        return None
    if time.time() > session['expires_at']:
        with SESSION_LOCK:
            SESSION_STORE.pop(session_id, None)
        return None
    return session

def sanitize_input(value):
    """Sanitize user input to prevent injection."""
    if not isinstance(value, str):
        return ''
    # Remove any non-alphanumeric characters except basic punctuation
    return re.sub(r'[^a-zA-Z0-9@._\-]', '', value)

def check_rate_limit(client_ip, max_requests=10, window=60):
    current_time = time.time()
    with RATE_LIMIT_LOCK:
        if client_ip not in RATE_LIMITS:
            RATE_LIMITS[client_ip] = []
        RATE_LIMITS[client_ip] = [t for t in RATE_LIMITS[client_ip] if current_time - t < window]
        if len(RATE_LIMITS[client_ip]) >= max_requests:
            return False
        RATE_LIMITS[client_ip].append(current_time)
        return True

def verify_auth_token(token):
    """Verify a signed authentication token.
    Token format: base64(payload).signature
    """
    if not token or '.' not in token:
        return None
    parts = token.rsplit('.', 1)
    if len(parts) != 2:
        return None
    payload_str, provided_sig = parts
    expected_sig = compute_mac(payload_str)
    # Verify signature
    if not constant_time_compare(expected_sig, provided_sig):
        return None
    try:
        payload = json.loads(payload_str)
    except (json.JSONDecodeError, ValueError):
        return None
    # Check expiration
    if 'exp' in payload and time.time() > payload['exp']:
        return None
    return payload

def create_auth_token(payload):
    """Create a signed authentication token."""
    payload_str = json.dumps(payload, separators=(',', ':'))
    sig = compute_mac(payload_str)
    return f"{payload_str}.{sig}"

class UserDatabase:
    """Simple in-memory user database with secure password storage."""
    def __init__(self):
        self._users = {}
        self._lock = threading.Lock()

    def register(self, username, password, role='user'):
        username = sanitize_input(username)
        if not username or len(username) < 3:
            return False, 'Invalid username'
        if len(password) < 8:
            return False, 'Password too short'
        with self._lock:
            if username in self._users:
                return False, 'User exists'
            salt = secrets.token_hex(16)
            pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
            self._users[username] = {
                'password_hash': pw_hash.hex(),
                'salt': salt,
                'role': role
            }
        return True, 'OK'

    def authenticate(self, username, password):
        username = sanitize_input(username)
        with self._lock:
            user = self._users.get(username)
        if user is None:
            # Constant-time fake computation to prevent user enumeration
            hashlib.pbkdf2_hmac('sha256', password.encode(), b'fakesalt1234567890123456789012', 100000)
            return None
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), user['salt'].encode(), 100000)
        if not constant_time_compare(pw_hash.hex(), user['password_hash']):
            return None
        return {'username': username, 'role': user['role']}

db = UserDatabase()
db.register('admin', 'SuperSecureP@ss1', role='admin')
