class AuthHandler(BaseHTTPRequestHandler):
    def get_client_ip(self):
        return self.client_address[0]

    def send_json(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

    def get_authenticated_user(self):
        """Extract and validate user from request.
        Supports both session cookies and bearer tokens."""
        # Try bearer token first
        auth_header = self.headers.get('Authorization', '')
        if auth_header.startswith('Bearer '):
            token = auth_header[7:]
            payload = verify_auth_token(token)
            if payload:
                return payload
        # Try session cookie
        cookie_header = self.headers.get('Cookie', '')
        for cookie in cookie_header.split(';'):
            cookie = cookie.strip()
            if cookie.startswith('session_id='):
                session_id = cookie[11:]
                session = validate_session(session_id)
                if session:
                    return session
        return None

    def check_admin_access(self, user):
        """Verify user has admin privileges.
        Strict role checking - only string 'admin' is accepted."""
        if user is None:
            return False
        role = user.get('role', '')
        if not isinstance(role, str):
            return False
        return role == 'admin'

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path

        if not check_rate_limit(self.get_client_ip()):
            self.send_json(429, {'error': 'Rate limited'})
            return

        if path == '/api/profile':
            user = self.get_authenticated_user()
            if not user:
                self.send_json(401, {'error': 'Unauthorized'})
                return
            self.send_json(200, {'user': user.get('username', user.get('user_id', 'unknown')), 'role': user.get('role', 'user')})

        elif path == '/api/admin/users':
            user = self.get_authenticated_user()
            if not user:
                self.send_json(401, {'error': 'Unauthorized'})
                return
            if not self.check_admin_access(user):
                self.send_json(403, {'error': 'Forbidden'})
                return
            self.send_json(200, {'users': ['admin', 'user1'], 'action': 'list'})

        elif path == '/api/admin/delete':
            user = self.get_authenticated_user()
            if not user:
                self.send_json(401, {'error': 'Unauthorized'})
                return
            if not self.check_admin_access(user):
                self.send_json(403, {'error': 'Forbidden'})
                return
            params = parse_qs(parsed.query)
            target = params.get('user', [''])[0]
            target = sanitize_input(target)
            self.send_json(200, {'deleted': target})

        else:
            self.send_json(404, {'error': 'Not found'})

    def do_POST(self):
        if not check_rate_limit(self.get_client_ip()):
            self.send_json(429, {'error': 'Rate limited'})
            return

        parsed = urlparse(self.path)
        path = parsed.path
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 10240:
            self.send_json(413, {'error': 'Payload too large'})
            return
        body = self.rfile.read(content_length)

        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self.send_json(400, {'error': 'Invalid JSON'})
            return

        if path == '/api/login':
            username = str(data.get('username', ''))
            password = str(data.get('password', ''))
            user_info = db.authenticate(username, password)
            if user_info is None:
                self.send_json(401, {'error': 'Invalid credentials'})
                return
            token_payload = {
                'username': user_info['username'],
                'role': user_info['role'],
                'exp': time.time() + 3600
            }
            token = create_auth_token(token_payload)
            session_id = create_session(user_info['username'], user_info['role'])
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Set-Cookie', f'session_id={session_id}; HttpOnly; SameSite=Strict')
            self.send_header('X-Content-Type-Options', 'nosniff')
            self.end_headers()
            self.wfile.write(json.dumps({'token': token}).encode())

        elif path == '/api/register':
            username = str(data.get('username', ''))
            password = str(data.get('password', ''))
            success, msg = db.register(username, password)
            if not success:
                self.send_json(400, {'error': msg})
                return
            self.send_json(201, {'message': 'User created'})

        else:
            self.send_json(404, {'error': 'Not found'})

    def log_message(self, format, *args):
        pass  # Suppress default logging

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), AuthHandler)
    print('Server running on 127.0.0.1:8080')
    server.serve_forever()
